316:  /// The detached switch: runs OUTSIDE the sequential line dispatch so the
317:  /// ambiguity picker's answer line can be routed to the pending prompt —
318:  /// awaiting the switch inline would deadlock the line REPL (the dispatch
319:  /// waits for the switch, the switch waits for the answer only the next
320:  /// dispatch could deliver — the reason the guided provider flows run
321:  /// detached too). The gate buffers input for the switch's lifetime; a
322:  /// second `/session` while one runs is ignored.
323:  Future<void> _switchSessionGated(String trimmed) {
324:    if (_providerFlowActive) return Future<void>.value();
325:    _providerFlowActive = true;
326:    return _switchSession(trimmed).whenComplete(() {
327:      _providerFlowActive = false;
328:      // Lines typed DURING the switch are real input, not flow junk —
329:      // redispatch them after the switch (in order), never drop them:
330:      // `/session new` + a prompt typed right after used to lose the
331:      // prompt to the flow-junk clear.
332:      final buffered = List<String>.of(_promptLineBuffer);
333:      _promptLineBuffer.clear();
334:      // The switch runs outside the dispatch's prompt lifecycle: redraw
335:      // the idle prompt so the status meter (zeroed by the switch) shows
336:      // in the transcript like it did when the switch was awaited inline.
337:      if (!_exited && !isBusy) _writeIdlePrompt();
338:      for (final line in buffered) {
339:        if (line.isNotEmpty) unawaited(_dispatchInput(line, line, const []));
340:      }
341:    });
