484:    for (final metadata in sessions) {
485:      if (metadata.id == wanted) return [metadata];
486:    }
487:    final repo = _repo;
488:    if (repo is! JsonlSessionRepo) {
489:      // Foreign repo implementation: no batch API - open per session.
490:      final matches = <SessionMetadata>[];
491:      for (final metadata in sessions) {
492:        final session = await _repo.open(metadata);
493:        final sessionName = await session.getSessionName();
494:        if (sessionName != null && sessionName.trim() == wanted) {
495:          matches.add(metadata);
