514:  /// Disambiguates same-named sessions: the LAUNCH folder's session beats a
515:  /// namesake from another project (the "fa --session X opens the wrong
516:  /// folder's session" bug); a clear single local wins silently, anything
517:  /// else is ambiguous and [onAmbiguous] receives the full match list so
518:  /// the caller can offer a choice. The fallback pick is the most recently
519:  /// updated local (or global when the folder has none).
520:  SessionMetadata? _resolveSessionNameMatch(
521:    List<SessionMetadata> matches, {
522:    void Function(List<SessionMetadata> matches)? onAmbiguous,
523:  }) {
524:    if (matches.isEmpty) return null;
525:    if (matches.length == 1) return matches.single;
526:    final local = [
527:      for (final m in matches)
528:        if (m.cwd == _env.cwd) m,
529:    ];
530:    if (local.length == 1) return local.single;
531:    onAmbiguous?.call(matches);
532:    final pool = local.isNotEmpty ? local : matches;
533:    pool.sort(
534:      (a, b) => (b.lastUpdatedAt ?? b.createdAt).compareTo(
535:        a.lastUpdatedAt ?? a.createdAt,
536:      ),
537:    );
538:    return pool.first;
539:  }
