562:  Future<Session> _loadSession(SessionMetadata metadata) async {
563:    final bootSw = Stopwatch()..start();
564:    // gh-968 parity: the budget must price the prompt the FIRST REQUEST
565:    // will carry. The messaging section joins at mailbox-prefix sync,
566:    // which runs after this walk in boot order — project the prefix
567:    // here so a resume cannot materialize one section more than the
568:    // live loop carried before exit (issue #1151: builtin-skills
569:    // metadata exhausted the record-bucket slack this race left).
570:    if (_subagentManager.messaging != null && metadata.id.isNotEmpty) {
571:      _assignMailboxPrefix(metadata.id);
572:    }
573:    void stage(String name) => _logDiagnostic(
574:      'boot_stage $name ms=${bootSw.elapsedMilliseconds} sid=${metadata.id}',
575:    );
576:    // Windowed open (owner directive): the CLI resume used to parse the
577:    // WHOLE file — 30s boots on marathon sessions. Open from the tail and
578:    // page back only to the newest compaction boundary; sessions without
579:    // compaction degenerate to the full load, so behavior is unchanged
580:    // for them. Context stays byte-identical: the compaction transform
581:    // drops everything before the boundary anyway.
582:    var session = await _repo.open(metadata, windowed: true);
583:    stage('open');
584:    // A marathon WITHOUT compaction pages past the windowed residency
585:    // cache — the leaf slides out and the branch would read empty (a
586:    // resume that looks like a fresh session, pty_resume_equivalence
587:    // AC6). Fall back to the full open: the documented degenerate path.
588:    //
589:    // Token budget (owner directive, issue #503 round 3): a resume needs
590:    // only the tail that fits the model's context window — walking a
591:    // marathon file back to the newest compaction parsed ~470MB / 11.5k
592:    // records (~10s) on a session whose window holds a fraction of that.
593:    //
594:    // gh-968 (AC-R3): the budget is the PARITY formula — effective
595:    // window minus the SAME unanchored system-prompt/tool-schema
596:    // overhead the ctx meter adds, minus the ACTIVE compaction reserve.
597:    // Pricing the transcript alone against the window (the old budget)
598:    // let a resume materialize MORE request than the live loop carried
599:    // before exit (the reported `127%/200k` footer): the meter read
600:    // transcript + overhead over the window and tripped the guard /
601:    // auto-compaction on a fresh resume. With the parity budget the
602:    // resumed meter sits at/below window − reserve — below the
603:    // compaction trigger — on every fresh resume.
604:    final budget = resumeParityBudget(
605:      effectiveContextWindow: _effectiveContextWindow,
606:      reserveTokens: _effectiveCompactionSettings.reserveTokens,
607:      systemPrompt: _agent.state.systemPrompt,
608:      tools: _agent.state.tools,
609:    );
610:    if (!await session.ensureCompactionBoundaryResident(tokenBudget: budget)) {
611:      session = await _repo.open(metadata);
612:    }
613:    stage('walk');
614:    final context = await session.buildContext();
615:    final messages = context.messages;
616:    stage('context');
617:    // Loaded usage anchors are generation-time: post-compaction they
618:    // phantom-report the pre-compaction size (183k on a 27k branch) and
619:    // fire a no-op compaction on every resume. Re-anchor at chars/4.
620:    _agent.state.messages = resetLoadedUsageAnchors(messages);
621:    _persistedCount = messages.length;
622:    // gh-1449 AC6: seed the one-shot orphan-report latch from the persisted
623:    // `orphan_report` records (raw scan — the windowed open drops side-leaf
624:    // custom records out of getEntries, the same reason the subagent
625:    // registry scans raw). A resumed session never re-reports an orphan
626:    // it already reported. Best-effort: a scan failure must not break boot.
627:    //
628:    // lastSegmentOnly (gh-1449 rework): the scan rides the RESUME BOOT
629:    // PATH, so it reads the primary segment only — orphan_report records
630:    // are tail-appended during runs, and the primary is rotation-bounded
631:    // (kSessionSegmentRotateBytes). A record already rotated into a
632:    // `.part-NN` segment may cost one re-report after a resume — the
633:    // accepted trade against the #503 whole-chain boot cost below.
634:    // clear() first: the Agent instance is reused across session opens,
635:    // so the latch must be strictly per-session.
636:    try {
637:      final repo = _repo;
638:      if (repo is JsonlSessionRepo) {
639:        final reports = await repo.readCustomRecordsOfType(metadata, {
640:          orphanReportRecordType,
641:        }, lastSegmentOnly: true);
642:        _agent.reportedOrphanKeys
643:          ..clear()
644:          ..addAll(orphanReportKeysFromRecords(reports));
645:      }
646:    } on Object catch (error) {
647:      _logDiagnostic('orphan_report seed failed sid=${metadata.id}: $error');
648:    }
649:    // Issue #437: persisted-but-unconsumed steering from a crashed
650:    // session re-enters the queue and wakes the idle agent (E1: one
651:    // record, consumed once — restart-safe).
652:    // Issue #503: NOT awaited — the scan reads the whole session file
653:    // (~1.5s on a 434MB marathon) and its result only arms the idle
654:    // wake, so it must not sit on the boot path. Fire-and-forget: the
