790:    _explicitToken = false;
791:    if (_restoreUsesRolesChain(entry, key)) {
792:      final applied = _repinRolesChain(
793:        resolver: config.modelRolesResolver!,
794:        spec: spec,
795:        built: built,
796:        entry: entry,
797:        key: key,
798:        previous: previous,
