import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

void main() {
  late MemoryExecutionEnv env;

  setUp(() {
    env = MemoryExecutionEnv(cwd: '/work');
  });

  group('folderModelStatePath', () {
    test('namespaces the state file under the encoded cwd', () {
      expect(
        folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work'),
        '/sessions/${encodeSessionCwd('/work')}/model-state.json',
      );
    });
  });

  group('folderModelStateApplies', () {
    test('applies when nothing explicit was given on this launch', () {
      expect(
        folderModelStateApplies(
          modelExplicit: false,
          providerExplicit: false,
          baseUrlExplicit: false,
          hasProviderPreconfig: false,
        ),
        isTrue,
      );
    });
    test('explicit launch flags win over the folder state', () {
      for (final (bool model, bool provider, bool baseUrl, bool preconfig) in [
        (true, false, false, false),
        (false, true, false, false),
        (false, false, true, false),
        (false, false, false, true),
      ]) {
        expect(
          folderModelStateApplies(
            modelExplicit: model,
            providerExplicit: provider,
            baseUrlExplicit: baseUrl,
            hasProviderPreconfig: preconfig,
          ),
          isFalse,
          reason: 'model=$model provider=$provider baseUrl=$baseUrl '
              'preconfig=$preconfig',
        );
      }
    });
  });

  group('save/load roundtrip', () {
    test('restores provider, model and base URL', () async {
      await saveFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
        providerKind: 'openai-completions',
        modelId: 'kimi-k2.6',
        baseUrl: 'https://api.example.com/v1',
      );
      final state = await loadFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
      );
      expect(
        state,
        const FolderModelState(
          providerKind: 'openai-completions',
          modelId: 'kimi-k2.6',
          baseUrl: 'https://api.example.com/v1',
        ),
      );
    });

    test('a null base URL survives the roundtrip', () async {
      await saveFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
        providerKind: 'anthropic',
        modelId: 'claude-x',
        baseUrl: null,
      );
      final state = await loadFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
      );
      expect(
        state,
        const FolderModelState(
          providerKind: 'anthropic',
          modelId: 'claude-x',
          baseUrl: null,
        ),
      );
    });

    test('folders do not see each other (per-folder scoping)', () async {
      await saveFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work/a',
        providerKind: 'openai-completions',
        modelId: 'model-a',
        baseUrl: null,
      );
      expect(
        await loadFolderModelState(
          env,
          sessionsRoot: '/sessions',
          cwd: '/work/b',
        ),
        isNull,
      );
    });
  });

  group('tolerant reads', () {
    test('a missing file loads as null', () async {
      expect(
        await loadFolderModelState(
          env,
          sessionsRoot: '/sessions',
          cwd: '/work',
        ),
        isNull,
      );
    });

    test('corrupt JSON loads as null', () async {
      final path = folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work');
      await env.writeFile(path, '{not json');
      expect(
        await loadFolderModelState(
          env,
          sessionsRoot: '/sessions',
          cwd: '/work',
        ),
        isNull,
      );
    });

    test('wrong field types load as null', () async {
      final path = folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work');
      await env.writeFile(
        path,
        jsonEncode({'providerKind': 42, 'modelId': ['x']}),
      );
      expect(
        await loadFolderModelState(
          env,
          sessionsRoot: '/sessions',
          cwd: '/work',
        ),
        isNull,
      );
    });

    test('a JSON array loads as null', () async {
      final path = folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work');
      await env.writeFile(path, '[1,2,3]');
      expect(
        await loadFolderModelState(
          env,
          sessionsRoot: '/sessions',
          cwd: '/work',
        ),
        isNull,
      );
    });

    test('a missing modelId loads as null', () async {
      final path = folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work');
      await env.writeFile(path, jsonEncode({'providerKind': 'anthropic'}));
      expect(
        await loadFolderModelState(
          env,
          sessionsRoot: '/sessions',
          cwd: '/work',
        ),
        isNull,
      );
    });
  });

  group('customProvider pin (gh-1000)', () {
    test('round-trips the pinned entry name', () async {
      await saveFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: 'https://api.kimi.com/coding/v1',
        customProvider: 'kimi_me',
      );
      final state = await loadFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
      );
      expect(state!.customProvider, 'kimi_me');
    });

    test('a pre-change state file loads with a null pin (AC4)', () async {
      final path = folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work');
      await env.writeFile(
        path,
        jsonEncode({
          'providerKind': 'openai-completions',
          'modelId': 'k3-256k',
          'baseUrl': 'https://api.kimi.com/coding/v1',
        }),
      );
      final state = await loadFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
      );
      expect(state, isNotNull);
      expect(state!.customProvider, isNull);
    });

    test('a non-string pin degrades to null', () async {
      final path = folderModelStatePath(sessionsRoot: '/sessions', cwd: '/work');
      await env.writeFile(
        path,
        jsonEncode({
          'providerKind': 'openai-completions',
          'modelId': 'k3-256k',
          'customProvider': 42,
        }),
      );
      final state = await loadFolderModelState(
        env,
        sessionsRoot: '/sessions',
        cwd: '/work',
      );
      expect(state!.customProvider, isNull);
    });

    CustomProviderRegistry registryWith() => CustomProviderRegistry([
      CustomProviderEntry(
        name: 'ira-1',
        apiType: 'kimi',
        baseUrl: 'https://api.kimi.com/coding/v1',
        modelId: 'k3-256k',
        keyName: 'FA_KEY_API_KIMI_COM_IRA_1',
      ),
      CustomProviderEntry(
        name: 'kimi_me',
        apiType: 'openai',
        baseUrl: 'https://api.kimi.com/coding/v1',
        modelId: 'k3-256k',
        keyName: 'FA_KEY_API_KIMI_COM_KIMI_ME',
      ),
    ]);

    test('pinnedEntry resolves the named entry among same-modelId twins '
        '(AC1)', () {
      final state = FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: 'https://api.kimi.com/coding/v1',
        customProvider: 'kimi_me',
      );
      final decision = folderStateProviderEntry(state, registryWith());
      expect(decision.entry, isNotNull);
      expect(decision.entry!.name, 'kimi_me');
      expect(decision.entry!.keyName, 'FA_KEY_API_KIMI_COM_KIMI_ME');
      expect(decision.note, isNull);
    });

    test('pin resolution is case-insensitive', () {
      final state = FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: 'https://api.kimi.com/coding/v1',
        customProvider: 'Kimi_Me',
      );
      expect(folderStateProviderEntry(state, registryWith()).entry!.name,
          'kimi_me');
    });

    test('a deleted entry yields the E1 note with the model kept', () {
      final state = FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: 'https://api.kimi.com/coding/v1',
        customProvider: 'gone-provider',
      );
      final decision = folderStateProviderEntry(state, registryWith());
      expect(decision.entry, isNull);
      expect(decision.note, contains('gone-provider'));
      expect(decision.note, contains('no longer configured'));
    });

    test('no pin → no entry and no note (legacy state)', () {
      final state = FolderModelState(
        providerKind: 'openai-completions',
        modelId: 'k3-256k',
        baseUrl: 'https://api.kimi.com/coding/v1',
      );
      final decision = folderStateProviderEntry(state, registryWith());
      expect(decision.entry, isNull);
      expect(decision.note, isNull);
    });

    test('a null state yields nothing', () {
      final decision = folderStateProviderEntry(null, registryWith());
      expect(decision.entry, isNull);
      expect(decision.note, isNull);
    });
  });
}

/// The JSONL session record model: the append-only tree of entries that
/// makes up a session, plus the file header.
///
/// Ported from pi-mono `packages/agent/src/harness/types.ts`
/// (`SessionTreeEntry` union) and `harness/session/jsonl-storage.ts`
/// (`SessionHeader`). A session file is a header line
/// (`{"type":"session","version":3,...}`) followed by one JSON record per
/// line; records form a tree through [SessionRecord.parentId], and `leaf`
/// records mark navigation of the active branch.
library;

import '../context.dart';
import '../types.dart';

/// The session header — always the first line of a JSONL session file.
///
/// Ported from pi's `SessionHeader` (version 3).
final class SessionHeader {
  /// Creates a [SessionHeader].
  const SessionHeader({
    required this.id,
    required this.timestamp,
    required this.cwd,
    this.parentSessionPath,
    this.metadata,
  });

  /// On-disk format version. Only version 3 is supported.
  static const version = 3;

  /// Format marker written into every segment header once a session has
  /// been rotated (gh-1077): a rotated session is a new on-disk format
  /// for pre-rotation builds — they read only the primary and either
  /// crash on the severed parent chain or silently miss the archived
  /// records. The marker (identical record format, higher version) makes
  /// an older build fail at header parse with a clear "unsupported
  /// session version" instead. This build accepts both [version] and
  /// [rotatedVersion].
  static const rotatedVersion = 4;

  /// Unique session id.
  final String id;

  /// When the session was created.
  final DateTime timestamp;

  /// Working directory the session belongs to.
  final String cwd;

  /// Path of the session this one was forked from, if any.
  final String? parentSessionPath;

  /// Free-form application metadata.
  final Map<String, dynamic>? metadata;

  /// Serializes to the header JSON line (without the trailing newline).
  Map<String, dynamic> toJson() => {
    'type': 'session',
    'version': version,
    'id': id,
    'timestamp': timestamp.toIso8601String(),
    'cwd': cwd,
    if (parentSessionPath != null) 'parentSession': parentSessionPath,
    if (metadata != null) 'metadata': metadata,
  };

  /// Deserializes and validates a header JSON map.
  ///
  /// Throws [FormatException] on any invalid field, mirroring pi's
  /// `parseHeaderLine` validation.
  factory SessionHeader.fromJson(Map<String, dynamic> json) {
    FormatException invalid(String message) =>
        FormatException('Invalid session header: $message');
    if (json['type'] != 'session') {
      throw invalid('first line is not a valid session header');
    }
    final headerVersion = json['version'];
    if (headerVersion != version && headerVersion != rotatedVersion) {
      throw invalid('unsupported session version');
    }
    if (json['id'] is! String || (json['id'] as String).isEmpty) {
      throw invalid('session header is missing id');
    }
    if (json['timestamp'] is! String || (json['timestamp'] as String).isEmpty) {
      throw invalid('session header is missing timestamp');
    }
    if (json['cwd'] is! String || (json['cwd'] as String).isEmpty) {
      throw invalid('session header is missing cwd');
    }
    final parentSession = json['parentSession'];
    if (parentSession != null && parentSession is! String) {
      throw invalid('session header parentSession must be a string');
    }
    final metadata = json['metadata'];
    if (metadata != null && metadata is! Map<String, dynamic>) {
      throw invalid('session header metadata must be an object');
    }
    return SessionHeader(
      id: json['id'] as String,
      timestamp: DateTime.parse(json['timestamp'] as String),
      cwd: json['cwd'] as String,
      parentSessionPath: parentSession as String?,
      metadata: metadata as Map<String, dynamic>?,
    );
  }
}

/// One entry in the append-only session tree.
///
/// Sealed counterpart of pi's `SessionTreeEntry` discriminated union. Every
/// record has a unique [id], an optional [parentId] forming the tree, and a
/// [timestamp]. Dispatch on the concrete type (or [type]) to read the
/// payload.
sealed class SessionRecord {
  /// Creates a [SessionRecord].
  const SessionRecord({
    required this.id,
    required this.parentId,
    required this.timestamp,
  });

  /// The type discriminator written to JSON (pi's `type` field).
  String get type;

  /// Unique record id (short random id generated by the storage).
  final String id;

  /// Id of the parent record, or `null` for a tree root.
  final String? parentId;

  /// When the record was created.
  final DateTime timestamp;

  /// Serializes to a JSON map with the `type` discriminator (pi shape).
  Map<String, dynamic> toJson() => {
    'type': type,
    'id': id,
    'parentId': parentId,
    'timestamp': timestamp.toIso8601String(),
    ...payloadJson(),
  };

  /// Type-specific fields merged into [toJson] by subclasses.
  Map<String, dynamic> payloadJson();

  /// Deserializes a record JSON map, dispatching on `type`.
  ///
  /// Throws [FormatException] for unknown types or invalid base fields,
  /// mirroring pi's `parseEntryLine` validation.
  factory SessionRecord.fromJson(Map<String, dynamic> json) {
    FormatException invalid(String message) =>
        FormatException('Invalid session record: $message');
    final type = json['type'];
    if (type is! String) throw invalid('missing entry type');
    final id = json['id'];
    if (id is! String || id.isEmpty) throw invalid('missing entry id');
    final parentId = json['parentId'];
    if (parentId != null && parentId is! String) {
      throw invalid('invalid parentId');
    }
    final timestampRaw = json['timestamp'];
    if (timestampRaw is! String || timestampRaw.isEmpty) {
      throw invalid('missing timestamp');
    }
    final timestamp = DateTime.parse(timestampRaw);
    return switch (type) {
      'message' => MessageRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        message: messageFromJson(
          (json['message'] as Map?)?.cast<String, dynamic>() ??
              const <String, dynamic>{},
        ),
      ),
      'thinking_level_change' => ThinkingLevelChangeRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        thinkingLevel: json['thinkingLevel'] as String? ?? 'off',
      ),
      'model_change' => ModelChangeRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        provider: json['provider'] as String? ?? '',
        modelId: json['modelId'] as String? ?? '',
        baseUrl: json['baseUrl'] as String?,
        customProvider: json['customProvider'] as String?,
      ),
      'active_tools_change' => ActiveToolsChangeRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        activeToolNames: [
          for (final name in (json['activeToolNames'] as List?) ?? const [])
            name as String,
        ],
      ),
      'compaction' => CompactionRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        summary: json['summary'] as String? ?? '',
        firstKeptEntryId: json['firstKeptEntryId'] as String? ?? '',
        tokensBefore: json['tokensBefore'] as int? ?? 0,
        details: json['details'],
        fromHook: json['fromHook'] as bool?,
      ),
      'branch_summary' => BranchSummaryRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        fromId: json['fromId'] as String? ?? '',
        summary: json['summary'] as String? ?? '',
        details: json['details'],
        fromHook: json['fromHook'] as bool?,
      ),
      'custom' => CustomRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        customType: json['customType'] as String? ?? '',
        data: json['data'],
      ),
      'checkpoint' => CheckpointRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        messageCount: json['messageCount'] as int? ?? 0,
        goal: json['goal'] as String?,
      ),
      'custom_message' => CustomMessageRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        customType: json['customType'] as String? ?? '',
        content: _parseCustomMessageContent(json['content']),
        display: json['display'] as bool? ?? false,
        details: json['details'],
      ),
      'label' => LabelRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        targetId: json['targetId'] as String? ?? '',
        label: json['label'] as String?,
      ),
      'session_info' => SessionInfoRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        name: json['name'] as String?,
      ),
      'hidden_range' => HiddenRangeRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        recordIds: [
          for (final recordId in (json['recordIds'] as List?) ?? const [])
            recordId as String,
        ],
      ),
      'compact_checkpoint' => CompactCheckpointRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        firstRecordId: json['firstRecordId'] as String? ?? '',
        lastRecordId: json['lastRecordId'] as String? ?? '',
        text: json['text'] as String? ?? '',
        coversRecordIds: [
          for (final recordId in (json['coversRecordIds'] as List?) ?? const [])
            recordId as String,
        ],
        flattenedRecordIds: [
          for (final recordId
              in (json['flattenedRecordIds'] as List?) ?? const [])
            recordId as String,
        ],
      ),
      'segment_pin' => SegmentPinRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        recordIds: [
          for (final recordId in (json['recordIds'] as List?) ?? const [])
            recordId as String,
        ],
        pinned: json['pinned'] as bool? ?? false,
      ),
      'leaf' => LeafRecord(
        id: id,
        parentId: parentId as String?,
        timestamp: timestamp,
        targetId: json['targetId'] as String?,
      ),
      _ => throw invalid('unknown entry type: $type'),
    };
  }
}

Object _parseCustomMessageContent(Object? content) {
  if (content is String) return content;
  return [
    for (final block in (content as List?) ?? const [])
      ContentBlock.fromJson((block as Map).cast<String, dynamic>()),
  ];
}

/// A conversation message appended to the tree.
///
/// Ported from pi's `MessageEntry`.
final class MessageRecord extends SessionRecord {
  /// Creates a [MessageRecord].
  const MessageRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
    required this.message,
  });

  /// The conversation message (user, assistant, or tool result).
  final Message message;

  @override
  String get type => 'message';

  @override
  Map<String, dynamic> payloadJson() => {'message': message.toJson()};
}

/// Records a change of the model's thinking level.
///
/// Ported from pi's `ThinkingLevelChangeEntry`.
final class ThinkingLevelChangeRecord extends SessionRecord {
  /// Creates a [ThinkingLevelChangeRecord].
  const ThinkingLevelChangeRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
    required this.thinkingLevel,
  });

  /// The new thinking level (e.g. `off`, `low`, `high`).
  final String thinkingLevel;

  @override
  String get type => 'thinking_level_change';

  @override
  Map<String, dynamic> payloadJson() => {'thinkingLevel': thinkingLevel};
}

/// Records a change of the active model.
///
/// Ported from pi's `ModelChangeEntry`. [baseUrl]/[customProvider] pin
/// the serving endpoint and saved custom-provider entry (gh-1000): a
/// session restore re-resolves onto THAT entry instead of re-matching by
/// model id. Both are optional — records written before gh-1000 restore
/// with today's endpoint-keyed behavior.
final class ModelChangeRecord extends SessionRecord {
  /// Creates a [ModelChangeRecord].
  const ModelChangeRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
    required this.provider,
    required this.modelId,
    this.baseUrl,
    this.customProvider,
  });

  /// The provider id (e.g. `anthropic`).
  final String provider;

  /// The model id.
  final String modelId;

  /// The endpoint base URL the model was served from (null = catalog
  /// default).
  final String? baseUrl;

  /// The saved custom-provider entry name that supplied the key (null =
  /// none or a pre-gh-1000 record).
  final String? customProvider;

  @override
  String get type => 'model_change';

  @override
  Map<String, dynamic> payloadJson() => {
    'provider': provider,
    'modelId': modelId,
    'baseUrl': ?baseUrl,
    'customProvider': ?customProvider,
  };
}

/// Records a change of the active tool set.
///
/// Ported from pi's `ActiveToolsChangeEntry`.
final class ActiveToolsChangeRecord extends SessionRecord {
  /// Creates an [ActiveToolsChangeRecord].
  const ActiveToolsChangeRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
    required this.activeToolNames,
  });

  /// Names of the tools active from this point on.
  final List<String> activeToolNames;

  @override
  String get type => 'active_tools_change';

  @override
  Map<String, dynamic> payloadJson() => {'activeToolNames': activeToolNames};
}

/// Marks a compaction point: [summary] replaces everything before
/// [firstKeptEntryId] when the context is rebuilt.
///
/// Ported from pi's `CompactionEntry`. Written by the compaction pipeline
/// (a later phase); the record type is defined here so the tree and context
/// projection already understand it.
final class CompactionRecord extends SessionRecord {
  /// Creates a [CompactionRecord].
  const CompactionRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
    required this.summary,
    required this.firstKeptEntryId,
    required this.tokensBefore,
    this.details,
    this.fromHook,
