558:  /// ride the summary as a hidden-segments index (issue #266 F1a) so the
559:  /// agent can consult and reopen what it can no longer see.
560:  Future<List<Message>> _projectMessages(
561:    List<SessionRecord> path, {
562:    List<SessionRecord> classicHidden = const [],
563:  }) async {
564:    final hasStructured = path.any(
565:      (entry) => entry is HiddenRangeRecord || entry is CompactCheckpointRecord,
