669:  /// The classic compaction cut: everything before the LAST
670:  /// [CompactionRecord]'s first-kept entry drops away; returns
671:  /// `(kept, dropped)` — dropped is what the summary folded away
672:  /// (issue #266 F1a). A path with no classic compaction passes through
673:  /// unchanged.
674:  (List<SessionRecord>, List<SessionRecord>) _applyCompactionTransform(
675:    List<SessionRecord> path,
676:  ) {
677:    CompactionRecord? compaction;
678:    var compactionIndex = -1;
679:    for (var i = 0; i < path.length; i++) {
680:      if (path[i] is CompactionRecord) {
681:        compaction = path[i] as CompactionRecord;
682:        compactionIndex = i;
683:      }
684:    }
685:    if (compaction == null) return (path, const []);
686:    final kept = <SessionRecord>[compaction];
687:    final dropped = <SessionRecord>[];
688:    var foundFirstKept = false;
689:    for (var i = 0; i < compactionIndex; i++) {
690:      if (path[i].id == compaction.firstKeptEntryId) foundFirstKept = true;
691:      if (foundFirstKept) {
692:        kept.add(path[i]);
693:      } else {
694:        dropped.add(path[i]);
695:      }
696:    }
697:    for (var i = compactionIndex + 1; i < path.length; i++) {
698:      kept.add(path[i]);
699:    }
700:    return (kept, dropped);
701:  }
